#!/usr/bin/env python3
import sys, pathlib, datetime, shutil, subprocess, os
RECOVERY='"""FSJ: recuperacao por WhatsApp com codigo de uso unico por 300 segundos."""\nimport hashlib, hmac, json, os, re, secrets, sqlite3, time\nfrom contextlib import contextmanager\n\nPREFIX = \'/api/password-recovery/\'\nTTL = 300\n\ndef configure(server):\n    folder = server.DATA / \'password-recovery\'\n    folder.mkdir(mode=0o700, parents=True, exist_ok=True)\n    path = folder / \'worker.json\'\n    if not path.exists():\n        value = json.dumps({\'secret\': secrets.token_urlsafe(48)})\n        fd = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)\n        with os.fdopen(fd, \'w\') as f: f.write(value)\n    config = json.loads(path.read_text())\n    return folder, config\n\n@contextmanager\ndef database(server):\n    folder, _ = configure(server)\n    path = folder / \'recovery.sqlite\'\n    c = sqlite3.connect(path, timeout=15)\n    c.row_factory = sqlite3.Row\n    os.chmod(path, 0o600)\n    try:\n        c.executescript(\'\'\'CREATE TABLE IF NOT EXISTS phones(uid TEXT PRIMARY KEY,phone TEXT NOT NULL);\nCREATE TABLE IF NOT EXISTS requests(id TEXT PRIMARY KEY,uid TEXT NOT NULL,phone TEXT NOT NULL,\ncode TEXT,hash TEXT NOT NULL,created REAL NOT NULL,expires REAL NOT NULL,status TEXT NOT NULL,\nattempts INTEGER NOT NULL DEFAULT 0,lease TEXT);\nCREATE INDEX IF NOT EXISTS requests_uid ON requests(uid,created);\'\'\')\n        with c: yield c\n    finally: c.close()\n\ndef phone_number(value):\n    value = re.sub(r\'\\D\', \'\', str(value))\n    if len(value) in (10, 11): value = \'55\' + value\n    if not re.fullmatch(r\'55[1-9][0-9]{9,10}\', value):\n        raise ValueError(\'Informe DDD e numero brasileiro do WhatsApp.\')\n    return value\n\ndef code_hash(secret, request, code):\n    return hmac.new(secret.encode(), (request + \':\' + code).encode(), hashlib.sha256).hexdigest()\n\ndef export_config(server):\n    import base64\n    _, cfg = configure(server)\n    ca = server.DATA / \'tls/fsj-ca.crt\'\n    return {\'url\':\'https://192.168.1.114:8443\', \'secret\':cfg[\'secret\'],\n            \'ca\':base64.b64encode(ca.read_bytes()).decode()}\n\ndef handle(handler, server, user, path):\n    if not path.startswith(PREFIX): return False\n    action = path[len(PREFIX):]\n    data = handler.body()\n    _, cfg = configure(server)\n    now = time.time()\n    def reply(status=200, **obj):\n        handler.reply(status, obj)\n        return True\n    if action.startswith(\'worker/\'):\n        auth = handler.headers.get(\'Authorization\', \'\')\n        if not hmac.compare_digest(auth, \'Bearer \' + cfg[\'secret\']):\n            return reply(403, error=\'Nao autorizado.\')\n        with database(server) as c:\n            c.execute(\'BEGIN IMMEDIATE\')\n            c.execute("UPDATE requests SET status=\'expired\',code=NULL WHERE expires<=? AND status NOT IN (\'used\',\'expired\')", (now,))\n            if action == \'worker/ping\': return reply(ok=True)\n            if action == \'worker/claim\':\n                row = c.execute("SELECT * FROM requests WHERE status=\'queued\' AND expires>? ORDER BY created LIMIT 1", (now+15,)).fetchone()\n                if not row: return reply(job=None)\n                lease = secrets.token_urlsafe(24)\n                c.execute("UPDATE requests SET status=\'sending\',lease=? WHERE id=?", (lease,row[\'id\']))\n                return reply(job={\'id\':row[\'id\'],\'phone\':row[\'phone\'],\'code\':row[\'code\'],\'expires\':row[\'expires\'],\'lease\':lease})\n            if action == \'worker/ack\':\n                ok = data.get(\'sent\') is True\n                c.execute("UPDATE requests SET status=?,code=NULL WHERE id=? AND lease=? AND status=\'sending\' AND expires>?",\n                          (\'sent\' if ok else \'failed\',str(data.get(\'id\',\'\')),str(data.get(\'lease\',\'\')),now))\n                return reply(ok=True)\n        return reply(404, error=\'Operacao indisponivel.\')\n    if action == \'owner/phone\':\n        if not user or user[\'role\'] != \'owner\': return reply(403,error=\'Somente o Proprietario pode confirmar contatos.\')\n        uid = str(data.get(\'id\',\'\'))\n        with server.db() as c:\n            target = c.execute(\'SELECT id FROM users WHERE id=?\',(uid,)).fetchone()\n            if not target: return reply(404,error=\'Conta nao encontrada.\')\n            phone = phone_number(data.get(\'phone\',\'\'))\n            server.audit(c,user[\'id\'],uid,\'recovery-phone-confirmed\')\n        with database(server) as c:\n            c.execute(\'INSERT OR REPLACE INTO phones(uid,phone) VALUES(?,?)\',(uid,phone))\n            c.execute("UPDATE requests SET status=\'cancelled\',code=NULL WHERE uid=? AND status!=\'used\'",(uid,))\n        return reply(ok=True)\n    if action == \'request\':\n        if not server.throttle((\'password-recovery-ip\',handler.client_address[0]),12,300):\n            return reply(429,error=\'Muitas solicitacoes. Aguarde cinco minutos.\')\n        name = str(data.get(\'name\',\'\')).strip().lower()\n        request = secrets.token_urlsafe(24)\n        with server.db() as c:\n            target = c.execute("SELECT id FROM users WHERE lower(name)=? AND status IN (\'active\',\'approved\')",(name,)).fetchone()\n        if target:\n            with database(server) as c:\n                c.execute(\'BEGIN IMMEDIATE\')\n                phone = c.execute(\'SELECT phone FROM phones WHERE uid=?\',(target[\'id\'],)).fetchone()\n                recent = c.execute(\'SELECT * FROM requests WHERE uid=? ORDER BY created DESC LIMIT 1\',(target[\'id\'],)).fetchone()\n                if phone and recent and now-recent[\'created\']<60 and recent[\'expires\']>now and recent[\'status\'] in (\'queued\',\'sending\',\'sent\'):\n                    request = recent[\'id\']\n                if phone and (not recent or now-recent[\'created\']>=60):\n                    code = str(secrets.randbelow(1000000)).zfill(6)\n                    c.execute("UPDATE requests SET status=\'cancelled\',code=NULL WHERE uid=? AND status!=\'used\'",(target[\'id\'],))\n                    c.execute("INSERT INTO requests(id,uid,phone,code,hash,created,expires,status) VALUES(?,?,?,?,?,?,?,\'queued\')",\n                              (request,target[\'id\'],phone[\'phone\'],code,code_hash(cfg[\'secret\'],request,code),now,now+TTL))\n                c.execute(\'DELETE FROM requests WHERE created<?\',(now-86400,))\n        return reply(request=request,expires_in=TTL,message=\'Se a conta estiver habilitada e tiver WhatsApp confirmado pelo Proprietario, o codigo sera enviado. Validade: 5 minutos.\')\n    if action == \'reset\':\n        if not server.throttle((\'password-recovery-verify\',handler.client_address[0]),30,300):\n            return reply(429,error=\'Muitas tentativas. Aguarde cinco minutos.\')\n        request = str(data.get(\'request\',\'\'))\n        code = str(data.get(\'code\',\'\')).strip()\n        password = data.get(\'password\')\n        server.check_password(password)\n        if password != data.get(\'confirmation\'): return reply(400,error=\'As senhas nao conferem.\')\n        accepted = False\n        with database(server) as c:\n            c.execute(\'ATTACH DATABASE ? AS mainapp\',(str(server.DATA/\'fsj.sqlite\'),))\n            c.execute(\'BEGIN IMMEDIATE\')\n            row = c.execute("SELECT * FROM requests WHERE id=? AND status=\'sent\' AND expires>? AND attempts<5",(request,now)).fetchone()\n            if row:\n                c.execute(\'UPDATE requests SET attempts=attempts+1 WHERE id=?\',(request,))\n                match = re.fullmatch(r\'[0-9]{6}\',code) and hmac.compare_digest(row[\'hash\'],code_hash(cfg[\'secret\'],request,code))\n                target = c.execute("SELECT id FROM mainapp.users WHERE id=? AND status IN (\'active\',\'approved\')",(row[\'uid\'],)).fetchone()\n                if match and target:\n                    salt = secrets.token_hex(16)\n                    c.execute("UPDATE mainapp.users SET hash=?,salt=?,status=\'active\',activation_hash=NULL,activation_expires=NULL WHERE id=?",\n                              (server.password_hash(password,salt),salt,row[\'uid\']))\n                    c.execute("UPDATE requests SET status=\'used\',code=NULL WHERE uid=?",(row[\'uid\'],))\n                    c.execute(\'INSERT INTO mainapp.account_audit(actor,target,action,created) VALUES(?,?,?,?)\',(row[\'uid\'],row[\'uid\'],\'password-reset-whatsapp\',now))\n                    accepted = row[\'uid\']\n                elif row[\'attempts\']+1>=5:\n                    c.execute("UPDATE requests SET status=\'locked\',code=NULL WHERE id=?",(request,))\n        if not accepted: return reply(400,error=\'Codigo invalido, expirado ou ainda nao enviado. Solicite outro se necessario.\')\n        server.revoke(accepted)\n        return reply(ok=True,message=\'Senha alterada. Entre com a nova senha.\')\n    return reply(404,error=\'Operacao indisponivel.\')\n'
UI='/* FSJ_PASSWORD_RECOVERY_V1 */\n;(()=>{\nconst login=document.getElementById(\'login\'),form=document.getElementById(\'loginForm\');\nif(!login||!form||document.getElementById(\'fsjForgotPassword\'))return;\nconst requestButton=document.createElement(\'button\');requestButton.type=\'button\';requestButton.id=\'fsjForgotPassword\';requestButton.textContent=\'Esqueci minha senha\';\nform.insertAdjacentElement(\'afterend\',requestButton);\nconst panel=document.createElement(\'section\');panel.className=\'card\';panel.id=\'fsjRecovery\';panel.hidden=true;\npanel.style.cssText=\'order:-1;flex:1;min-height:0;overflow:auto\';\npanel.innerHTML=\'<h2>Recuperar senha</h2><form id="fsjRecoveryRequest"><label>Login<input id="fsjRecoveryName" autocomplete="username" required maxlength="40"></label><p>O codigo sera enviado automaticamente ao WhatsApp confirmado pelo Proprietario. Ele vale por 5 minutos.</p><button>Enviar codigo pelo WhatsApp</button></form><form id="fsjRecoveryReset" hidden><label>Codigo recebido<input id="fsjRecoveryCode" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" required></label><label>Nova senha<input id="fsjRecoveryPassword" type="password" minlength="10" maxlength="200" autocomplete="new-password" required></label><label>Confirmar nova senha<input id="fsjRecoveryConfirmation" type="password" minlength="10" maxlength="200" autocomplete="new-password" required></label><button type="button" id="fsjRecoveryShow">Mostrar senhas</button><button type="submit">Salvar nova senha</button><button type="button" id="fsjRecoveryResend">Solicitar outro codigo</button></form><p id="fsjRecoveryStatus" role="status" aria-live="polite"></p><button type="button" id="fsjRecoveryBack">Voltar para entrar</button>\';\nlogin.insertAdjacentElement(\'afterend\',panel);\nlet ticket=null;\nconst el=id=>document.getElementById(id);\nasync function post(action,data){const response=await fetch(\'/api/password-recovery/\'+action,{method:\'POST\',headers:{\'Content-Type\':\'application/json\',\'X-FSJ-Request\':\'1\'},body:JSON.stringify(data),signal:AbortSignal.timeout(20000)});const result=await response.json();if(!response.ok)throw Error(result.error||\'Nao foi possivel concluir.\');return result;}\nfunction back(){ticket=null;panel.hidden=true;login.hidden=false;el(\'fsjRecoveryReset\').reset();el(\'fsjRecoveryStatus\').textContent=\'\';}\nrequestButton.onclick=()=>{login.hidden=true;const download=el(\'androidDownload\');if(download)download.hidden=true;panel.hidden=false;el(\'fsjRecoveryName\').value=el(\'name\').value;el(\'fsjRecoveryRequest\').hidden=false;el(\'fsjRecoveryReset\').hidden=true;el(\'fsjRecoveryName\').focus();};\nel(\'fsjRecoveryBack\').onclick=back;\nel(\'fsjRecoveryResend\').onclick=()=>{ticket=null;el(\'fsjRecoveryRequest\').hidden=false;el(\'fsjRecoveryReset\').hidden=true;el(\'fsjRecoveryReset\').reset();el(\'fsjRecoveryStatus\').textContent=\'Solicite outro codigo. Aguarde pelo menos um minuto entre envios.\';};\nel(\'fsjRecoveryShow\').onclick=()=>{const show=el(\'fsjRecoveryPassword\').type===\'password\';for(const id of [\'fsjRecoveryPassword\',\'fsjRecoveryConfirmation\'])el(id).type=show?\'text\':\'password\';el(\'fsjRecoveryShow\').textContent=show?\'Ocultar senhas\':\'Mostrar senhas\';el(\'fsjRecoveryShow\').setAttribute(\'aria-pressed\',String(show));};\nel(\'fsjRecoveryRequest\').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector(\'button\');button.disabled=true;try{const data=await post(\'request\',{name:el(\'fsjRecoveryName\').value});ticket=data.request;el(\'fsjRecoveryRequest\').hidden=true;el(\'fsjRecoveryReset\').hidden=false;el(\'fsjRecoveryStatus\').textContent=data.message;el(\'fsjRecoveryCode\').focus();}catch(error){el(\'fsjRecoveryStatus\').textContent=error.message;}finally{button.disabled=false;}};\nel(\'fsjRecoveryReset\').onsubmit=async event=>{event.preventDefault();if(!ticket)return;const button=event.target.querySelector(\'[type="submit"]\');button.disabled=true;try{const data=await post(\'reset\',{request:ticket,code:el(\'fsjRecoveryCode\').value,password:el(\'fsjRecoveryPassword\').value,confirmation:el(\'fsjRecoveryConfirmation\').value});back();el(\'password\').value=\'\';const message=el(\'status\');if(message)message.textContent=data.message;}catch(error){el(\'fsjRecoveryStatus\').textContent=error.message;}finally{button.disabled=false;}};\n// O contato de recuperacao so pode ser definido por uma sessao do Proprietario.\nconst details=el(\'accountDetails\');\nif(details){\nconst button=document.createElement(\'button\');button.type=\'button\';button.textContent=\'Confirmar WhatsApp de recuperacao\';details.insertAdjacentElement(\'afterend\',button);\nbutton.onclick=async()=>{\nconst account=el(\'accountSelect\')?.value;if(!account){alert(\'Selecione uma pessoa cadastrada.\');return;}\nconst phone=prompt(\'WhatsApp confirmado desta pessoa (DDD e numero):\');if(phone===null)return;\nif(!confirm(\'Confirma que este WhatsApp pertence a pessoa selecionada? \'+phone))return;\nbutton.disabled=true;try{await post(\'owner/phone\',{id:account,phone});alert(\'WhatsApp de recuperacao confirmado.\');}catch(error){alert(error.message);}finally{button.disabled=false;}\n};\n}\n})();\n'
HOOK="  if path.startswith('/api/password-recovery/'):\n   import recovery, sys\n   return recovery.handle(self,sys.modules[__name__],user,path)\n"
CSS="\n/* FSJ_PASSWORD_RECOVERY_V1 */\nbody:has(#login:not([hidden])) main{overflow-y:auto}body:has(#login:not([hidden])) #login{order:-1;flex:none;overflow:visible}#fsjForgotPassword{display:block;width:100%;margin:5px 0}#fsjRecovery label{font-size:14px;margin:5px 0}#fsjRecovery input{font-size:16px;padding:7px}#fsjRecovery p{font-size:13px}\n"
def install(root,restart=True):
 root=pathlib.Path(root).resolve()
 files=[root/'server.py',root/'static/app.js',root/'static/style.css']
 old=[p.read_text() for p in files]
 anchor="  path=urlparse(self.path).path; user=self.user()\n"
 if old[0].count(anchor)!=1:raise SystemExit('Servidor diferente do esperado. Nada alterado.')
 new=[old[0] if HOOK in old[0] else old[0].replace(anchor,anchor+HOOK,1),old[1] if 'FSJ_PASSWORD_RECOVERY_V1' in old[1] else old[1]+'\n'+UI,old[2] if 'FSJ_PASSWORD_RECOVERY_V1' in old[2] else old[2]+CSS]
 compile(new[0],str(files[0]),'exec');compile(RECOVERY,'recovery.py','exec')
 extra=root/'recovery.py'
 if extra.exists() and extra.read_text()!=RECOVERY:raise SystemExit('Modulo de recuperacao diferente. Nada alterado.')
 if extra.exists() and new==old:
  print('Recuperacao ja instalada.');return
 backup=root/'backups'/('recuperacao-whatsapp-'+datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f'));backup.mkdir(parents=True)
 for p in files:shutil.copy2(p,backup/p.name)
 existed=extra.exists()
 if existed:shutil.copy2(extra,backup/extra.name)
 try:
  extra.write_text(RECOVERY)
  for p,t in zip(files,new):
   tmp=p.with_name(p.name+'.recovery.tmp');tmp.write_text(t);shutil.copymode(p,tmp);os.replace(tmp,p)
  sys.path.insert(0,str(root))
  import recovery, server
  recovery.configure(server)
  if restart:subprocess.run(['systemctl','--user','restart','fsj-reserva.service'],check=True)
 except BaseException:
  for p in files:shutil.copy2(backup/p.name,p)
  if existed:shutil.copy2(backup/extra.name,extra)
  else:extra.unlink(missing_ok=True)
  if restart:subprocess.run(['systemctl','--user','restart','fsj-reserva.service'])
  raise
 print('INSTALADO NA VM: Esqueci minha senha; codigo de uso unico por 5 minutos.')
 print('Backup:',backup)
 print('Proximo passo: vincular o WhatsApp de recuperacao no Windows e confirmar os numeros pelo Proprietario.')
 print('Contas, senhas existentes, videos e rotina das 7h preservados.')
if __name__=='__main__':install(sys.argv[1] if len(sys.argv)>1 else str(pathlib.Path.home()/'fsj-video-v001'))
